export const BODY: string = "\n<p>تقليل صورة إلى 100 كيلوبايت عمل يستغرق خمس دقائق عندما تتبع الخطوات الصحيحة. لا حاجة إلى برامج معقدة أو خبرة في التحرير.</p>\n<p>يغطي هذا الدليل سير العمل كاملًا. ستختار ملف المصدر المناسب، وتختار صيغة الإخراج، وتضغط، وتراجع النتيجة قبل الرفع.</p>\n<p>يعمل ذلك للسير الذاتية وبوابات التوظيف وصور المدونات ورسوم البريد، على الهاتف أو الحاسوب، دون تثبيت أي شيء.</p>\n<h2 id=\"what-you-need\">ما الذي تحتاجه قبل البدء؟</h2>\n<p>تحتاج إلى ثلاثة أشياء قبل البدء: الصورة الأصلية بأعلى جودة، ومعرفة حد البوابة والصيغة المقبولة، ومتصفح حديث.</p>\n<p>إذا كانت صورتك لقطة شاشة، فابحث عن الملف الأصلي. لقطات الشاشة تحمل ضجيجًا يجعل الوصول إلى 100 كيلوبايت أصعب دون داعٍ.</p>\n<h2 id=\"step-1-open-the-tool\">الخطوة 1: افتح أداة 100 كيلوبايت</h2>\n<p>افتح <a href=\"/ar/daght-as-sura-ila-100kb/\">أداة ضغط الصورة إلى 100 كيلوبايت</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصورة إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تسجيل. افتح الصفحة وابدأ فورًا، وستبقى صورتك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع الصورة</h2>\n<p>أسقط صورتك في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات JPG وPNG وWebP وHEIC، بحجم إدخال يصل إلى 25 ميغابايت.</p>\n<p>إذا رفعت عدة صور، فستظهر كل واحدة في قائمة. يمكنك ضبط الإعدادات لكل صورة أو تطبيق الإعداد نفسه على الكل.</p>\n<h2 id=\"step-3-choose-format\">الخطوة 3: اختر صيغة الإخراج</h2>\n<p>للصور الفوتوغرافية اختر JPG. يعطي أصغر ملف بأفضل جودة، وتقبله كل البوابات دون استثناء تقريبًا.</p>\n<p>للنصوص والرسوم المسطحة اختر PNG، وللشعارات الشفافة جرّب WebP إذا قبلته بوابتك. اختيار الصيغة الصحيح يختصر نصف المشكلة.</p>\n<h2 id=\"step-4-run-compression\">الخطوة 4: نفّذ الضغط</h2>\n<p>اضغط زر الضغط واترك الأداة تعمل. تبحث تلقائيًا عن أعلى جودة تناسب 100 كيلوبايت، فلا تحتاج إلى تخمين الأرقام.</p>\n<p>تستغرق العملية ثواني معدودة لصورة واحدة. الصور الكبيرة جدًا قد تأخذ وقتًا أطول قليلًا، لكنها تنتهي بسرعة عادة.</p>\n<h2 id=\"step-5-preview\">الخطوة 5: راجع النتيجة بعناية</h2>\n<p>قبل التنزيل، قارن النتيجة بالأصل. كبّر الصورة وافحص الوجه أو النص، وتأكد من أن التفاصيل المهمة ما زالت واضحة.</p>\n<p>إذا بدت النتيجة ناعمة أكثر من اللازم، فأعد الضغط من الملف الأصلي مع قص أذكى، لا من النسخة المضغوطة.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ونظّم</h2>\n<p>نزّل الملف وسمِّه باسم واضح مثل sora-sira-100kb.jpg. الاسم الواضح يمنع الخلط عندما تحتاج الملف بعد أشهر.</p>\n<p>أنشئ مجلدًا لكل غرض: سيرة ذاتية، مدونة، بريد. التنظيم البسيط يوفر عليك البحث لاحقًا ويمنع رفع الملف الخاطئ.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>إذا لم يصل الملف إلى 100 كيلوبايت، فغيّر الصيغة إلى JPG أولًا. PNG هو السبب الأكثر شيوعًا لفشل الوصول إلى الهدف مع الصور الفوتوغرافية.</p>\n<p>وإذا استمرت المشكلة، اسمح بتقليص الأبعاد أو قصّ الصورة بإحكام. كل بكسل تزيله يحرّر مساحة من ميزانية 100 كيلوبايت.</p>\n<h2 id=\"resume-photo-workflow\">سير العمل: صورة سيرة ذاتية</h2>\n<p>لصورة سيرة ذاتية، ابدأ بصورة شخصية بإضاءة نهارية وخلفية بسيطة. قصّها مربعة حول الوجه، ثم اضغط إلى 100 كيلوبايت.</p>\n<p>راجع النتيجة بالتكبير على الوجه والعينين. إذا بدت واضحة، فالملف جاهز للرفع إلى بوابة التوظيف.</p>\n<h2 id=\"blog-thumbnail-workflow\">سير العمل: صور المدونة المصغرة</h2>\n<p>للصور المصغرة للمدونة، قصّ الصورة إلى نسبة العرض المطلوبة أولًا، ثم اضغط إلى 100 كيلوبايت. القص أولًا يعطي نتيجة أنظف.</p>\n<p>استخدم الاسم نفسه لملف الصورة وعنوان المقالة تقريبًا. ذلك يساعد محركات البحث على فهم موضوع الصورة.</p>\n<h2 id=\"phone-workflow\">سير العمل: على هاتفك</h2>\n<p>كل الخطوات تعمل على الهاتف. افتح الأداة في المتصفح وارفع الصورة من معرضك، ثم عاين ونزّل دون نقل الملف إلى حاسوب.</p>\n<p>على الشاشات الصغيرة، استخدم التكبير بإصبعيك لفحص النتيجة. إذا بدت واضحة في التكبير، فهي جاهزة.</p>\n<h2 id=\"certificate-scans\">كيف تقلّل مسح الشهادات والمستندات؟</h2>\n<p>مسح الشهادات والمستندات يُضغط جيدًا لأن معظمه مساحة بيضاء. امسح بدقة 200 نقطة في البوصة واحفظ بصيغة JPG.</p>\n<p>إذا كان النص صغيرًا، فلا تخفض الجودة بقوة. قلّص الأبعاد تدريجيًا بدلًا من ذلك، لأن النص يتحسس من فقدان الحدة.</p>\n<h2 id=\"comparing-results\">كيف تستخدم عرض المقارنة جيدًا؟</h2>\n<p>عرض المقارنة يضع الأصل والنتيجة جنبًا إلى جنب. حرّك المنزلق بينهما لترى الفرق الحقيقي في التفاصيل.</p>\n<p>ركّز على المناطق المهمة: الوجه والنص والحواف. إذا كانت هذه واضحة، فبقية الصورة مقبولة عادة.</p>\n<h2 id=\"auto-convert-png\">خيار التحويل التلقائي لملفات PNG الكبيرة</h2>\n<p>إذا رفعت ملف PNG كبيرًا، فقد تقترح الأداة تحويله تلقائيًا إلى JPG. اقبل الاقتراح للصور الفوتوغرافية، فهو يختصر الطريق إلى 100 كيلوبايت.</p>\n<p>احتفظ بـPNG فقط للنصوص والرسوم التي تحتاج حدة كاملة أو شفافية. لكل شيء آخر، JPG أفضل وأصغر.</p>\n<h2 id=\"recompress-warning\">تحذير إعادة الضغط: ماذا يعني؟</h2>\n<p>تحذير إعادة الضغط يعني أنك ضغطت نسخة مضغوطة أصلًا. كل جولة تضيف ضررًا، لذلك توقف وابحث عن الملف الأصلي.</p>\n<p>إذا لم يعد الأصل متوفرًا، فاقبل النتيجة الحالية بدل المزيد من الضغط. إعادة الضغط لن تحسّن الصورة أبدًا.</p>\n<h2 id=\"keeping-originals-safe\">كيف تحافظ على ملفاتك الأصلية آمنة؟</h2>\n<p>لا تحذف الملفات الأصلية بعد الضغط. البوابات تغيّر قواعدها، وقد تحتاج نسخة أكبر لاحقًا، والملف المضغوط لا يعود إلى جودته الأصلية.</p>\n<p>احتفظ بالأصل في مجلد منفصل مع نسخة احتياطية. هذه العادة البسيطة تنقذك عندما يتغير حد البوابة.</p>\n<h2 id=\"team-workflows\">سير عمل 100 كيلوبايت للفرق</h2>\n<p>للفرق، وحّد الإعدادات: صيغة JPG وهدف 100 كيلوبايت وأبعاد ثابتة لكل نوع صورة. التوحيد يمنع اختلاف النتائج بين أعضاء الفريق.</p>\n<p>شارك مجلدًا مشتركًا للنسخ المضغوطة المعتمدة، حتى لا يعيد كل شخص ضغط الصورة نفسها بإعدادات مختلفة.</p>\n<h2 id=\"alt-text-seo\">النص البديل وأسماء الملفات وتحسين محركات البحث عند 100 كيلوبايت</h2>\n<p>النص البديل واسم الملف جزء من تحسين محركات البحث. اكتب نصًا بديلًا يصف الصورة فعلًا، وسمِّ الملف بكلمات مفتاحية عربية واضحة.</p>\n<p>تجنب الأسماء العامة مثل IMG_4821.jpg. اسم مثل daght-sura-100kb.jpg لا يساعد محركات البحث، بينما اسم عربي واضح يصف المحتوى أفضل.</p>\n<h2 id=\"measuring-improvement\">كيف تقيس التحسن بعد الضغط؟</h2>\n<p>قارن سرعة تحميل صفحتك قبل الضغط وبعده. أدوات قياس السرعة المجانية تظهر الفرق بوضوح، وعادة يتحسن وقت التحميل بشكل ملحوظ.</p>\n<p>تابع أيضًا معدل ارتداد الزوار. الصفحات الأسرع تحتفظ بالزوار مدة أطول، وهذا هدف الضغط الحقيقي لا مجرد تصغير الأرقام.</p>\n<h2 id=\"rounding-note\">ملاحظة عن أحجام الملفات والتقريب</h2>\n<p>انتبه إلى التقريب: بعض الأنظمة تحسب الكيلوبايت 1000 بايت، وبعضها 1024 بايت. لذلك قد يظهر ملف 100 كيلوبايت عندك بحجم مختلف قليلًا على جهاز آخر.</p>\n<p>القاعدة الآمنة أن تستهدف أقل بقليل من الحد، مثل 96 أو 98 كيلوبايت. بهذا تتجاوز البوابة مهما كان نظام التقريب لديها. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-100kb/\">الدليل الكامل لضغط الصورة إلى 100 كيلوبايت</a> وقارن الصيغ في <a href=\"/ar/blog/jawdat-suwar-100kb-wa-al-siyagh/\">جودة صورة 100 كيلوبايت: JPG مقابل PNG مقابل WebP</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-50kb/\">ضاغط 50 كيلوبايت</a> للحدود الأصغر.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكنني تقليل صورة إلى 100 كيلوبايت بالضبط؟","answer":"الأداة تستهدف أقل من 100 كيلوبايت لا الرقم بالضبط. إذا كانت أفضل جودة ممكنة تنتج 96 كيلوبايت، فهذا هو الملف الصحيح. أي ملف تحت الحد يجتاز البوابة."},{"question":"ما أفضل صيغة لتقليل صورة إلى 100 كيلوبايت؟","answer":"JPG غالبًا الأفضل للصور الفوتوغرافية، لأنه يعطي أصغر ملف بأفضل جودة. WebP يتفوق بهامش صغير لكن بعض البوابات ترفضه. PNG يناسب النصوص والرسوم فقط."},{"question":"هل يمكنني تقليل لقطة PNG إلى 100 كيلوبايت دون تضبيب النص؟","answer":"نعم، إذا حافظت على الأبعاد كبيرة. النص يحتاج حدة، فخفض الجودة بقوة يضبّب الحروف. قصّ اللقطة على المنطقة المهمة أولًا، ثم اضغط بخفض تدريجي وراجع النص بالتكبير."},{"question":"كم صورة يمكنني تقليلها إلى 100 كيلوبايت دفعة واحدة؟","answer":"بأداة الضغط الجماعي، يمكنك معالجة عشرات الصور دفعة واحدة. ارفع المجلد كاملًا وحدد هدف 100 كيلوبايت، ثم نزّل النتائج كملف ZIP واحد."},{"question":"هل يزيل تقليل صورتي إلى 100 كيلوبايت بياناتها الوصفية؟","answer":"نعم، تزيل الأداة بيانات EXIF ووسوم موقع GPS أثناء الضغط. الملف المنزّل لا يحمل موقع التقاط الصورة ولا معلومات الكاميرا، وهذا جيد للخصوصية."},{"question":"صورتي تزن 90 كيلوبايت أصلًا. هل يجب تمريرها عبر الأداة؟","answer":"ليس ضروريًا. إذا كانت الصورة 90 كيلوبايت أصلًا وتبدو جيدة، فارفعها كما هي. مرّرها عبر الأداة فقط إذا أردت إزالة البيانات الوصفية أو توحيد الصيغة."}];
